create extension if not exists pgcrypto;
create table if not exists users (id uuid primary key default gen_random_uuid(), phone_number text not null unique, display_name text, age integer check (age is null or age between 1 and 120), xp bigint not null default 0 check (xp >= 0), level integer not null default 1 check (level > 0), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists groups (id uuid primary key default gen_random_uuid(), jid text not null unique, name text not null default '', is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table if not exists group_members (group_id uuid references groups(id) on delete cascade, user_id uuid references users(id) on delete cascade, is_admin boolean not null default false, created_at timestamptz not null default now(), primary key (group_id, user_id));
create table if not exists bot_settings (key text primary key, value jsonb not null, updated_at timestamptz not null default now());
create table if not exists sudo_users (user_id uuid primary key references users(id) on delete cascade, added_by uuid references users(id), created_at timestamptz not null default now());
create table if not exists warnings (id uuid primary key default gen_random_uuid(), group_id uuid not null references groups(id) on delete cascade, user_id uuid not null references users(id) on delete cascade, reason text not null default '', created_at timestamptz not null default now());
create table if not exists mutes (group_id uuid references groups(id) on delete cascade, user_id uuid references users(id) on delete cascade, expires_at timestamptz, created_at timestamptz not null default now(), primary key (group_id, user_id));
create table if not exists bans (group_id uuid references groups(id) on delete cascade, user_id uuid references users(id) on delete cascade, reason text not null default '', created_at timestamptz not null default now(), primary key (group_id, user_id));
create table if not exists economy (user_id uuid primary key references users(id) on delete cascade, coins bigint not null default 0 check (coins >= 0), last_daily timestamptz, last_work timestamptz, updated_at timestamptz not null default now());
create table if not exists inventory (user_id uuid references users(id) on delete cascade, item_key text, quantity integer not null default 0 check (quantity >= 0), primary key (user_id, item_key));
create table if not exists pets (id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, name text not null, species text not null, hunger integer not null default 100 check (hunger between 0 and 100), created_at timestamptz not null default now());
create table if not exists vehicles (id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, name text not null, created_at timestamptz not null default now());
create table if not exists quests (id uuid primary key default gen_random_uuid(), user_id uuid not null references users(id) on delete cascade, quest_key text not null, progress integer not null default 0 check (progress >= 0), completed boolean not null default false, unique (user_id, quest_key));
create table if not exists plugin_settings (plugin_name text primary key, enabled boolean not null default true, updated_at timestamptz not null default now());
create table if not exists daily_reports (id uuid primary key default gen_random_uuid(), report_date date not null unique, messages integer not null default 0, groups_count integer not null default 0, private_chats integer not null default 0, media_count integer not null default 0, moderation_events integer not null default 0, status_events integer not null default 0, created_at timestamptz not null default now());
create index if not exists warnings_group_user_idx on warnings(group_id, user_id); create index if not exists daily_reports_date_idx on daily_reports(report_date); create index if not exists users_xp_idx on users(xp desc);
